/bin/bash -lc "python - <<'PY'
import json
for file in ['book-model.json','positive-profiles.json','prerequisite-context.json','native-national-scope.json','memory-cards.json','description-review-input.json','batch.input.jsonl','attached-images.json']:
 t=open(file).read()
 a=json.loads(t.splitlines()[0] if file.endswith('jsonl') else t)
 print(file,type(a).__name__,list(a.keys()) if isinstance(a,dict) else len(a))
 if isinstance(a,dict):
  for k,v in a.items():
   print(' ',k, type(v).__name__,len(v) if isinstance(v,(list,dict)) else '',list(v[0].keys()) if isinstance(v,list) and v and isinstance(v[0],dict) else '')
 elif a: print(list(a[0].keys()))
PY"

